-- Robotics/Embedded/IoT pathway ("Vector Division") Act 23 -- "Mapping &
-- SLAM" content, under world-vec-mapping-and-slam (already inserted
-- separately, act-vec-4, index 22, closing Arc IV's mapping thread). 1
-- campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other Act. This Act closes the
-- "old maps lie" thread that has run since Act 18 (the arm's
-- undocumented frame) and Act 20 (the mobile robots' identical
-- signature) -- Dr. Lin Ortega finally lets a robot build and verify its
-- own map instead of trusting an old one, and proves the corridor
-- genuinely changed rather than drifted.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-mapping-and-slam', 'world-vec-mapping-and-slam', 'mapping-and-slam', '4F - Mapping & SLAM', 'Learn how a robot builds a map it can actually trust -- occupancy grids, mapping from range sensors, the joint localization-and-mapping problem, SLAM intuition, loop closure, pose graphs, map drift, 2D and visual SLAM concepts, and map quality -- while Dr. Lin Ortega proves a corridor''s geometry genuinely changed, closing a question she has been chasing since the day an arm''s coordinates first refused to make sense.', 23);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-mapping-and-slam-1', 'campaign-vec-mapping-and-slam', 'building-the-map-as-you-go', 'Building the Map As You Go', 'Maps, occupancy grids, mapping from range sensors, localization plus mapping, SLAM intuition and loop closure.', 1),
  ('operation-vec-mapping-and-slam-2', 'campaign-vec-mapping-and-slam', 'the-map-you-can-trust', 'The Map You Can Trust', 'Pose graphs, map drift, 2D SLAM concepts, visual SLAM concepts, map quality and the corridor that moved.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-mapping-and-slam-01', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-1', 'maps', 'Maps', 'A robot just finished the first full SLAM pass across a facility corridor, and the geometry it measured does not match the decades-old blueprint at all. Before Vector Division decides which one is wrong, Dr. Lin Ortega insists on agreeing what a map actually is.', 'beginner', ARRAY['imani','lin','byte'], null, null, '{"type":"simulation","simulationId":"maps-sim"}'::jsonb, '{"xp":300,"credits":25}'::jsonb, false, 1),
  ('mission-vec-mapping-and-slam-02', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-1', 'occupancy-grids', 'Occupancy Grids', 'A map is not a photograph. An occupancy grid divides the world into cells and asks one question of each: occupied, free, or genuinely unknown.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"occupancy-grids-sim"}'::jsonb, '{"xp":300,"credits":30}'::jsonb, false, 2),
  ('mission-vec-mapping-and-slam-03', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-1', 'mapping-from-range-sensors', 'Mapping from Range Sensors', 'A single range reading only draws one line through space. Turning thousands of overlapping readings into a coherent grid is the actual work of building a map from what a robot can measure.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"mapping-from-range-sensors-sim"}'::jsonb, '{"xp":310,"credits":30}'::jsonb, false, 3),
  ('mission-vec-mapping-and-slam-04', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-1', 'localization-plus-mapping', 'Localization Plus Mapping', 'Knowing where you are requires a map. Building a map requires knowing where you were standing. Neither can simply be solved first here, because the corridor already gave Vector Division a reason to distrust the one map it has.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"localization-plus-mapping-sim"}'::jsonb, '{"xp":310,"credits":35}'::jsonb, false, 4),
  ('mission-vec-mapping-and-slam-05', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-1', 'slam-intuition', 'SLAM Intuition', 'SLAM does not solve localization, then mapping. It estimates both at once, letting an improving map sharpen the position estimate and an improving position estimate sharpen the map, together.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"slam-intuition-sim"}'::jsonb, '{"xp":320,"credits":35}'::jsonb, false, 5),
  ('mission-vec-mapping-and-slam-06', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-1', 'loop-closure', 'Loop Closure', 'The robot returns to a junction it has already passed through this run. Recognizing that correctly, and only correctly, is what lets Vector Division tighten a map that has been quietly drifting the whole time.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"loop-closure-sim"}'::jsonb, '{"xp":320,"credits":35}'::jsonb, false, 6),
  ('mission-vec-mapping-and-slam-07', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-2', 'pose-graphs', 'Pose Graphs', 'Every pose the robot has estimated, and every relationship between them, can be drawn as a graph. Fixing the map ends up meaning: making that graph agree with itself.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"pose-graphs-sim"}'::jsonb, '{"xp":330,"credits":40}'::jsonb, false, 7),
  ('mission-vec-mapping-and-slam-08', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-2', 'map-drift', 'Map Drift', 'Small errors that never get corrected do not stay small. Left alone across a long run they accumulate into a map that looks confident and is quietly wrong -- and Vector Division has to prove this corridor is not just that.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"map-drift-sim"}'::jsonb, '{"xp":330,"credits":40}'::jsonb, false, 8),
  ('mission-vec-mapping-and-slam-09', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-2', '2d-slam', '2D SLAM', 'Most warehouse-floor mapping never needs a third dimension. 2D SLAM builds a flat occupancy grid from a single scanning plane, and it is exactly the tool this corridor needs first.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"2d-slam-concepts-sim"}'::jsonb, '{"xp":340,"credits":40}'::jsonb, false, 9),
  ('mission-vec-mapping-and-slam-10', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-2', 'visual-slam', 'Visual SLAM', 'Not every robot carries a range sensor. A camera alone can build a map too, by tracking the same visual features across many frames instead of ranging distance directly.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"visual-slam-concepts-sim"}'::jsonb, '{"xp":340,"credits":45}'::jsonb, false, 10),
  ('mission-vec-mapping-and-slam-11', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-2', 'map-quality', 'Map Quality', 'A finished map is not automatically a trustworthy one. Before Vector Division commits to what SLAM just built, it has to be checked against the same standards any map has to meet.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"map-quality-sim"}'::jsonb, '{"xp":350,"credits":45}'::jsonb, false, 11),
  ('mission-vec-mapping-and-slam-12', 'world-vec-mapping-and-slam', 'campaign-vec-mapping-and-slam', 'operation-vec-mapping-and-slam-2', 'the-corridor-that-moved', 'The Corridor That Moved', 'Everything this Act taught, turned on one corridor: prove its geometry genuinely changed, rule out drift and sensor error, and confirm the new SLAM-built map is one Vector Division can actually trust -- closing a question Dr. Lin Ortega has been chasing since the first day an arm''s coordinates refused to make sense.', 'boss', ARRAY['imani','lin','byte'], '{"requiredMissionIds":["mission-vec-mapping-and-slam-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-corridor-that-moved-boss-sim"}'::jsonb, '{"xp":1650,"credits":340,"badgeIds":["the-corridor-that-moved"],"skillXp":{"robotics_fundamentals":230}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-mapping-and-slam-01', 1, 'imani', 'A robot just finished the first full SLAM pass across this facility, and the corridor it mapped does not match the blueprint. Not by a little. Dr. Ortega, this is yours before it becomes a path-planning problem.'),
  ('mission-vec-mapping-and-slam-01', 2, 'lin', 'Good. Before we decide whether that corridor is wrong or the blueprint is wrong, we need to agree on what a map even is. It is not the truth. It is somebody''s best representation of the truth, built at some specific moment, using whatever sensors or surveys existed then.'),
  ('mission-vec-mapping-and-slam-01', 3, 'lin', 'That blueprint was drawn decades ago. This SLAM pass was built an hour ago from what the robot could actually measure. Neither one gets to be trusted automatically just because it is older, or because it is newer.'),
  ('mission-vec-mapping-and-slam-01', 4, 'byte', 'I have the raw scan. The corridor measures roughly 1.8 meters narrower than the blueprint claims, over an eleven-meter stretch. That is not a rounding error.'),
  ('mission-vec-mapping-and-slam-01', 5, 'lin', 'No, it is not. And it is exactly the kind of number I do not want anyone guessing about. We start from first principles: what a map is, how one gets built, and only then do we ask which one here is lying.'),

  ('mission-vec-mapping-and-slam-02', 1, 'lin', 'An occupancy grid is the simplest honest map there is. Divide the world into cells. For each cell, ask one question only: is this space occupied, is it free, or do we not know yet.'),
  ('mission-vec-mapping-and-slam-02', 2, 'lin', 'Three states, not two. Unknown is not a failure to fill in later -- it is real information. It means no sensor has ever actually looked there.'),

  ('mission-vec-mapping-and-slam-03', 1, 'lin', 'A single range reading is one line drawn through space -- everything short of the hit is probably free, the hit itself is probably occupied. One reading proves almost nothing on its own.'),
  ('mission-vec-mapping-and-slam-03', 2, 'byte', 'But thousands of them, taken from different positions as the robot moves, overlap. Where readings agree, confidence in a cell climbs. Where they disagree, the grid stays honest and marks it uncertain instead of guessing.'),

  ('mission-vec-mapping-and-slam-04', 1, 'lin', 'Here is the trap. To localize accurately, you want a good map. To build a good map, you need to know accurately where you were standing when each reading was taken. Neither one is free.'),
  ('mission-vec-mapping-and-slam-04', 2, 'lin', 'Normally we would just localize against the blueprint and move on. Not this corridor -- we already have a reason to think that blueprint might not be telling the truth. The map has to be earned honestly here, not borrowed.'),

  ('mission-vec-mapping-and-slam-05', 1, 'lin', 'SLAM does not solve those two problems in order. It solves them together, at the same time, each one correcting the other as new data arrives.'),
  ('mission-vec-mapping-and-slam-05', 2, 'lin', 'A better map sharpens where the robot thinks it is. A better position estimate sharpens where new readings actually belong on the map. Run that loop enough times and both converge.'),

  ('mission-vec-mapping-and-slam-06', 1, 'lin', 'Every SLAM run accumulates small errors. Loop closure is the one moment that can fix them: the robot recognizes it has arrived somewhere it has already been, and that recognition lets it correct everything measured in between.'),
  ('mission-vec-mapping-and-slam-06', 2, 'byte', 'Recognizing correctly matters more than recognizing quickly. Match the wrong place and you do not close a loop, you corrupt the whole map with a false correction.'),

  ('mission-vec-mapping-and-slam-07', 1, 'lin', 'A pose graph draws the robot''s whole trajectory as points, one per estimated position, connected by edges. Each edge is a constraint -- what the robot''s own sensors measured about how those two poses relate.'),
  ('mission-vec-mapping-and-slam-07', 2, 'lin', 'When a loop closure adds a new edge, it rarely agrees perfectly with everything already in the graph. Optimizing the graph means spreading that disagreement out sensibly across every edge, not just patching the one segment that closed.'),

  ('mission-vec-mapping-and-slam-08', 1, 'lin', 'Drift is what happens when small per-step errors are never corrected. They do not cancel out. They accumulate, and a map built entirely without loop closure looks confident while being quietly, increasingly wrong.'),
  ('mission-vec-mapping-and-slam-08', 2, 'byte', 'Which is the obvious explanation for this corridor too -- except drift has a signature, and I want to check whether this discrepancy actually matches it before anyone assumes that is what happened here.'),

  ('mission-vec-mapping-and-slam-09', 1, 'lin', 'Most of what Vector Division needs on a warehouse floor lives in a single horizontal plane. 2D SLAM builds a flat occupancy grid from one scanning plane, and it is enough to navigate almost any indoor facility.'),
  ('mission-vec-mapping-and-slam-09', 2, 'lin', 'It will not tell you about a shelf overhanging at head height. It will tell you, reliably, whether the floor ahead is clear. That trade-off is deliberate, not a limitation anyone forgot about.'),

  ('mission-vec-mapping-and-slam-10', 1, 'lin', 'Not every robot carries a range sensor. Visual SLAM builds a map from a camera alone, by tracking the same distinctive features across many frames and working out how the camera itself must have moved to see them shift that way.'),
  ('mission-vec-mapping-and-slam-10', 2, 'lin', 'It trades range precision for cost and weight. And it opens up loop closure by sight -- recognizing a place because it looks the same, not because a range scan matches.'),

  ('mission-vec-mapping-and-slam-11', 1, 'lin', 'A finished map is not automatically a good one. Before Vector Division commits to anything built from this pass, it has to clear the same bar every map does: is it consistent with itself, does it cover what it claims to, and is it current.'),
  ('mission-vec-mapping-and-slam-11', 2, 'lin', 'A map can be perfectly self-consistent and still be dangerously out of date. Consistency proves the map agrees with itself. It does not, by itself, prove the world still looks like that.'),

  ('mission-vec-mapping-and-slam-12', 1, 'imani', 'Three SLAM passes, three different days, and the corridor still comes back the same wrong width. Before we touch a single path plan, I want an answer I can stand behind: is that corridor lying to us, or is the blueprint?'),
  ('mission-vec-mapping-and-slam-12', 2, 'lin', 'I have been chasing a version of this question since the day I first looked at that arm''s coordinates and could not tell you what they were relative to. An undocumented frame misplaced an arm. The same undocumented frame drifted six mobile robots. I do not think this corridor is a coincidence.'),
  ('mission-vec-mapping-and-slam-12', 3, 'byte', 'It is not. I pulled the occupancy grids from all three passes and overlaid them. Same width, same location, down to the resolution of the grid, every single time.'),
  ('mission-vec-mapping-and-slam-12', 4, 'lin', 'That rules out drift on its own. Drift is never that clean -- it grows with distance, it varies run to run, it does not reproduce itself to the centimeter three times in a row. Something out there actually changed.'),
  ('mission-vec-mapping-and-slam-12', 5, 'lin', 'And loop closure backs the new map, not the blueprint. The robot came back around to its own starting junction and recognized it with high confidence. Residual error across the whole loop settled near zero. This map agrees with itself, and it was built from what is actually there today.'),
  ('mission-vec-mapping-and-slam-12', 6, 'imani', 'Then say it plainly -- for this corridor, and for every report still sitting in that fleet audit that we filed under malfunctioning instead of under this.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-mapping-and-slam-01-o1', 'mission-vec-mapping-and-slam-01', 1, 'Define what a map actually is', 'Choose the accurate definition of what a map represents to a mobile robot''s software stack.'),
  ('mission-vec-mapping-and-slam-01-o2', 'mission-vec-mapping-and-slam-01', 2, 'Weigh the mismatch', 'Judge which finding makes the corridor mismatch worth investigating rather than dismissing.'),

  ('mission-vec-mapping-and-slam-02-o1', 'mission-vec-mapping-and-slam-02', 1, 'Sort a scan into a grid', 'Sort each sensor finding into the correct occupancy grid cell state.'),
  ('mission-vec-mapping-and-slam-02-o2', 'mission-vec-mapping-and-slam-02', 2, 'Defend the unknown state', 'Choose the accurate explanation for why a grid keeps a separate unknown state instead of just free or occupied.'),

  ('mission-vec-mapping-and-slam-03-o1', 'mission-vec-mapping-and-slam-03', 1, 'Order ray casting', 'Order the steps that turn one range reading into a grid update.'),
  ('mission-vec-mapping-and-slam-03-o2', 'mission-vec-mapping-and-slam-03', 2, 'Explain why one scan is not enough', 'Choose the accurate reason a single scan cannot finish a reliable map.'),

  ('mission-vec-mapping-and-slam-04-o1', 'mission-vec-mapping-and-slam-04', 1, 'Name the chicken-and-egg problem', 'Choose the accurate statement of the joint localization-and-mapping problem.'),
  ('mission-vec-mapping-and-slam-04-o2', 'mission-vec-mapping-and-slam-04', 2, 'Explain why borrowing the blueprint will not work', 'Find the evidence explaining why localizing against the existing blueprint is not a safe shortcut for this corridor.'),

  ('mission-vec-mapping-and-slam-05-o1', 'mission-vec-mapping-and-slam-05', 1, 'Define SLAM correctly', 'Choose the accurate description of what SLAM actually estimates.'),
  ('mission-vec-mapping-and-slam-05-o2', 'mission-vec-mapping-and-slam-05', 2, 'Order the refinement loop', 'Order the stages of SLAM''s repeating refinement cycle.'),

  ('mission-vec-mapping-and-slam-06-o1', 'mission-vec-mapping-and-slam-06', 1, 'Define loop closure', 'Choose the accurate definition of loop closure.'),
  ('mission-vec-mapping-and-slam-06-o2', 'mission-vec-mapping-and-slam-06', 2, 'Confirm a genuine match', 'Find the evidence confirming this is a genuine loop closure rather than a superficially similar junction.'),

  ('mission-vec-mapping-and-slam-07-o1', 'mission-vec-mapping-and-slam-07', 1, 'Read a pose graph', 'Order a pose graph''s components from raw measurement to a consistent trajectory.'),
  ('mission-vec-mapping-and-slam-07-o2', 'mission-vec-mapping-and-slam-07', 2, 'Explain what optimization actually fixes', 'Choose the accurate description of what pose graph optimization does with a newly closed loop.'),

  ('mission-vec-mapping-and-slam-08-o1', 'mission-vec-mapping-and-slam-08', 1, 'Define drift', 'Choose the accurate description of map drift.'),
  ('mission-vec-mapping-and-slam-08-o2', 'mission-vec-mapping-and-slam-08', 2, 'Know drift''s signature', 'Find the evidence describing what typical drift actually looks like, so it can later be told apart from a genuine change.'),

  ('mission-vec-mapping-and-slam-09-o1', 'mission-vec-mapping-and-slam-09', 1, 'Define 2D SLAM', 'Choose the accurate description of what 2D SLAM builds and why it is enough for most indoor navigation.'),
  ('mission-vec-mapping-and-slam-09-o2', 'mission-vec-mapping-and-slam-09', 2, 'Know 2D SLAM''s blind spot', 'Find the evidence identifying a hazard 2D SLAM cannot see, given it scans a single plane.'),

  ('mission-vec-mapping-and-slam-10-o1', 'mission-vec-mapping-and-slam-10', 1, 'Define visual SLAM', 'Choose the accurate description of how visual SLAM builds a map without a range sensor.'),
  ('mission-vec-mapping-and-slam-10-o2', 'mission-vec-mapping-and-slam-10', 2, 'Judge the trade-off', 'Find the evidence describing what visual SLAM gives up compared to range-based SLAM.'),

  ('mission-vec-mapping-and-slam-11-o1', 'mission-vec-mapping-and-slam-11', 1, 'Sort quality criteria', 'Sort each property into an actual map-quality criterion or not.'),
  ('mission-vec-mapping-and-slam-11-o2', 'mission-vec-mapping-and-slam-11', 2, 'Separate consistency from correctness', 'Choose the accurate statement about what internal consistency does and does not prove.'),

  ('mission-vec-mapping-and-slam-12-o1', 'mission-vec-mapping-and-slam-12', 1, 'Prove the corridor genuinely changed', 'Find the evidence proving the corridor''s real geometry differs from the blueprint through consistent occupancy-grid measurement.'),
  ('mission-vec-mapping-and-slam-12-o2', 'mission-vec-mapping-and-slam-12', 2, 'Rule out drift and sensor error', 'Find the evidence that rules out accumulated drift or sensor error as the explanation for the mismatch.'),
  ('mission-vec-mapping-and-slam-12-o3', 'mission-vec-mapping-and-slam-12', 3, 'Confirm the new map is trustworthy', 'Find the evidence proving loop closure made the new SLAM map internally consistent.'),
  ('mission-vec-mapping-and-slam-12-o4', 'mission-vec-mapping-and-slam-12', 4, 'Close the case', 'Having proven all three, state what actually happened to the corridor and what it means for Vector Division''s old maps.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-mapping-and-slam-01-o1-c1', 'mission-vec-mapping-and-slam-01-o1', 1, 'multiple_choice', 'Which best describes what a map means to a robot''s software stack?', '{"question":"Which best describes what a map means to a robot''s software stack?","options":[{"id":"a","text":"A permanent, guaranteed-accurate record of the physical environment"},{"id":"b","text":"A representation of the environment built at some specific time, using whatever sensors or surveys existed then -- accurate only as of that moment"},{"id":"c","text":"A live video feed with no persistence"},{"id":"d","text":"Whatever facilities filed most recently, always"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mapping-and-slam-01-o2-c1', 'mission-vec-mapping-and-slam-01-o2', 1, 'investigation', 'Which finding tells Vector Division this mismatch is worth investigating rather than dismissing as sensor noise?', '{"evidence":[{"id":"e1","label":"SLAM scan report","detail":"Corridor measures roughly 1.8 meters narrower than the blueprint over an eleven-meter stretch"},{"id":"e2","label":"Odometry log","detail":"Robot''s own odometry stayed within expected tolerance for a run this length"},{"id":"e3","label":"Facilities note","detail":"The blueprint''s last formal revision predates the current facility management system by decades"}],"question":"Which finding tells Vector Division this mismatch is worth investigating rather than dismissing as sensor noise?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-mapping-and-slam-02-o1-c1', 'mission-vec-mapping-and-slam-02-o1', 1, 'drag_and_drop', 'Sort each sensor finding into the correct occupancy grid cell state.', '{"items":[{"id":"i1","text":"A range reading hits a wall 4 meters out"},{"id":"i2","text":"The space between the sensor and that wall, along the beam"},{"id":"i3","text":"A spot behind the wall no beam has ever reached"},{"id":"i4","text":"A doorway the robot has driven straight through repeatedly"}],"targets":[{"id":"occupied","label":"Occupied"},{"id":"free","label":"Free"},{"id":"unknown","label":"Unknown"}]}'::jsonb, '{"correctMapping":{"i1":"occupied","i2":"free","i3":"unknown","i4":"free"}}'::jsonb),
  ('mission-vec-mapping-and-slam-02-o2-c1', 'mission-vec-mapping-and-slam-02-o2', 1, 'multiple_choice', 'Why does an occupancy grid need a separate unknown state, instead of just free or occupied?', '{"question":"Why does an occupancy grid need a separate unknown state, instead of just free or occupied?","options":[{"id":"a","text":"It does not need one, unknown is just a bug"},{"id":"b","text":"Unknown marks a cell no sensor has actually observed yet -- guessing it as free or occupied would report information the robot does not have"},{"id":"c","text":"Unknown means the sensor detected static or noise"},{"id":"d","text":"Unknown is only used for cells outside the robot''s current battery range"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-mapping-and-slam-03-o1-c1', 'mission-vec-mapping-and-slam-03-o1', 1, 'interactive_diagram', 'Order the steps that turn one range reading into a grid update.', '{"diagramId":"range-sensor-ray-casting","hotspots":[{"id":"sense_range","label":"Take a range reading","explanation":"The sensor reports a distance and direction to whatever it hit."},{"id":"cast_ray","label":"Cast a ray along that direction","explanation":"Trace a line from the sensor''s position out to the reported distance."},{"id":"mark_free","label":"Mark cells along the ray as free","explanation":"Every cell the ray passes through before the hit is probably clear space."},{"id":"mark_occupied","label":"Mark the endpoint cell as occupied","explanation":"The cell where the ray actually terminates is probably a surface."}],"task":"Order the steps from taking the reading to updating the grid."}'::jsonb, '{"correctOrderIds":["sense_range","cast_ray","mark_free","mark_occupied"]}'::jsonb),
  ('mission-vec-mapping-and-slam-03-o2-c1', 'mission-vec-mapping-and-slam-03-o2', 1, 'multiple_choice', 'Why can a single range scan never finish a reliable occupancy grid on its own?', '{"question":"Why can a single range scan never finish a reliable occupancy grid on its own?","options":[{"id":"a","text":"Because sensors are always broken on the first reading"},{"id":"b","text":"Because a single scan only observes what is visible from one position -- overlapping scans from many positions are what let confidence in each cell actually build up"},{"id":"c","text":"Because grids require exactly 1000 readings by definition"},{"id":"d","text":"Because occupancy grids are always three-dimensional"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-mapping-and-slam-04-o1-c1', 'mission-vec-mapping-and-slam-04-o1', 1, 'multiple_choice', 'What is the core difficulty that makes localization and mapping hard to solve separately?', '{"question":"What is the core difficulty that makes localization and mapping hard to solve separately?","options":[{"id":"a","text":"There is no real difficulty, they are unrelated problems"},{"id":"b","text":"Accurate localization needs a good map, and building a good map needs accurate localization -- neither can be fully solved first without the other"},{"id":"c","text":"Mapping only matters for outdoor robots"},{"id":"d","text":"Localization is always solved by GPS, making the problem trivial"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mapping-and-slam-04-o2-c1', 'mission-vec-mapping-and-slam-04-o2', 1, 'investigation', 'Which evidence explains why localizing this robot against the existing blueprint is not a safe shortcut here?', '{"evidence":[{"id":"e1","label":"Scan comparison","detail":"The corridor''s measured width already disagrees with the blueprint by 1.8 meters"},{"id":"e2","label":"Facilities note","detail":"No renovation record exists for this section of the facility"},{"id":"e3","label":"Robot log","detail":"The robot''s battery was at 82 percent during the scan"}],"question":"Which evidence explains why localizing this robot against the existing blueprint is not a safe shortcut here?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-mapping-and-slam-05-o1-c1', 'mission-vec-mapping-and-slam-05-o1', 1, 'multiple_choice', 'SLAM stands for simultaneous localization and mapping. What does simultaneous actually mean here?', '{"question":"SLAM stands for simultaneous localization and mapping. What does simultaneous actually mean here?","options":[{"id":"a","text":"Localization and mapping run on separate robots at the same time"},{"id":"b","text":"Both the robot''s position and the map are estimated together, each cycle using the current map to refine the position and the current position to refine the map"},{"id":"c","text":"SLAM only runs once, instantly, at the start of a mission"},{"id":"d","text":"It means mapping happens first, then localization happens simultaneously afterward"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mapping-and-slam-05-o2-c1', 'mission-vec-mapping-and-slam-05-o2', 1, 'interactive_diagram', 'Order the stages of SLAM''s repeating refinement cycle.', '{"diagramId":"slam-refinement-loop","hotspots":[{"id":"gather","label":"Gather new sensor data","explanation":"New range or visual readings arrive as the robot moves."},{"id":"update_pose","label":"Update the pose estimate","explanation":"Use the current map to refine where the robot most likely is now."},{"id":"update_map","label":"Update the map estimate","explanation":"Use the refined pose to place the new readings correctly on the map."},{"id":"repeat","label":"Repeat","explanation":"The loop runs continuously as the robot keeps moving."}],"task":"Order SLAM''s refinement loop from new data to the next cycle."}'::jsonb, '{"correctOrderIds":["gather","update_pose","update_map","repeat"]}'::jsonb),

  ('mission-vec-mapping-and-slam-06-o1-c1', 'mission-vec-mapping-and-slam-06-o1', 1, 'multiple_choice', 'What does loop closure actually accomplish?', '{"question":"What does loop closure actually accomplish?","options":[{"id":"a","text":"It ends a SLAM session automatically"},{"id":"b","text":"Recognizing that the robot has returned to a previously visited place, which lets the accumulated error across the whole path in between be corrected at once"},{"id":"c","text":"It closes any open doors along the corridor"},{"id":"d","text":"It deletes older parts of the map to save memory"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mapping-and-slam-06-o2-c1', 'mission-vec-mapping-and-slam-06-o2', 1, 'investigation', 'Which evidence actually confirms this is a genuine loop closure, not just a superficially similar junction?', '{"evidence":[{"id":"e1","label":"Feature match report","detail":"Current scan matches 94 percent of distinctive features recorded at this junction earlier in the same run, in the same relative arrangement"},{"id":"e2","label":"Coarse similarity","detail":"Junction shape is broadly rectangular, like several other junctions in the facility"},{"id":"e3","label":"Timestamp","detail":"The candidate match occurred 40 minutes into the run"}],"question":"Which evidence actually confirms this is a genuine loop closure, not just a superficially similar junction?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-mapping-and-slam-07-o1-c1', 'mission-vec-mapping-and-slam-07-o1', 1, 'interactive_diagram', 'Order a pose graph''s components from raw measurement to a consistent trajectory.', '{"diagramId":"pose-graph-structure","hotspots":[{"id":"nodes","label":"Nodes","explanation":"Each node is one estimated robot pose at some point in the run."},{"id":"edges","label":"Edges","explanation":"Each edge is a constraint -- what sensors measured about the relationship between two poses."},{"id":"loop_edge","label":"Loop closure edge","explanation":"A new edge added when the robot recognizes a previously visited pose, usually disagreeing slightly with the existing graph."},{"id":"optimize","label":"Graph optimization","explanation":"Adjust every node so the whole graph agrees with its edges as closely as possible."}],"task":"Order the pose graph pipeline from raw structure to a consistent trajectory."}'::jsonb, '{"correctOrderIds":["nodes","edges","loop_edge","optimize"]}'::jsonb),
  ('mission-vec-mapping-and-slam-07-o2-c1', 'mission-vec-mapping-and-slam-07-o2', 1, 'multiple_choice', 'A loop closure edge disagrees with the graph built so far. What does pose graph optimization do about it?', '{"question":"A loop closure edge disagrees with the graph built so far. What does pose graph optimization do about it?","options":[{"id":"a","text":"Deletes the new edge since it disagrees"},{"id":"b","text":"Keeps only the original path and ignores the new edge"},{"id":"c","text":"Spreads the disagreement out across every pose in the graph, adjusting each one a little so the whole trajectory becomes internally consistent, rather than patching just the closed segment"},{"id":"d","text":"Restarts the entire SLAM run from scratch"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-vec-mapping-and-slam-08-o1-c1', 'mission-vec-mapping-and-slam-08-o1', 1, 'multiple_choice', 'What is map drift?', '{"question":"What is map drift?","options":[{"id":"a","text":"A map physically sliding on a server"},{"id":"b","text":"Small per-step errors that are never corrected, accumulating over a run into a map that looks confident while being increasingly wrong"},{"id":"c","text":"A deliberate feature that improves map accuracy over time"},{"id":"d","text":"An error that only ever affects visual SLAM, never range-based SLAM"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mapping-and-slam-08-o2-c1', 'mission-vec-mapping-and-slam-08-o2', 1, 'investigation', 'Which evidence describes what typical drift looks like, so this corridor''s discrepancy can later be checked against it?', '{"evidence":[{"id":"e1","label":"Drift research note","detail":"Uncorrected odometry drift typically grows roughly with distance traveled and varies from run to run, depending on surface, speed and turns taken"},{"id":"e2","label":"Byte''s comparison","detail":"This corridor''s discrepancy is identical in magnitude and location across three independent passes on different days"},{"id":"e3","label":"Sensor spec sheet","detail":"The range sensor''s rated accuracy is plus or minus 2 centimeters"}],"question":"Which evidence describes what typical drift looks like, so this corridor''s discrepancy can later be checked against it?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-mapping-and-slam-09-o1-c1', 'mission-vec-mapping-and-slam-09-o1', 1, 'multiple_choice', 'What does 2D SLAM actually build, and why is it usually enough for a warehouse floor?', '{"question":"What does 2D SLAM actually build, and why is it usually enough for a warehouse floor?","options":[{"id":"a","text":"A full 3D model of the facility, simplified for display"},{"id":"b","text":"A flat occupancy grid from a single scanning plane, which is sufficient because most navigation only needs to know whether the floor ahead is clear"},{"id":"c","text":"A grid that only works outdoors"},{"id":"d","text":"A map with no relationship to real-world distance"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mapping-and-slam-09-o2-c1', 'mission-vec-mapping-and-slam-09-o2', 1, 'investigation', 'Given the sensor only scans one plane, which evidence describes a hazard 2D SLAM would miss entirely?', '{"evidence":[{"id":"e1","label":"Sensor mounting note","detail":"The 2D range sensor scans a single horizontal plane at a fixed height"},{"id":"e2","label":"Facility hazard report","detail":"A shelf bracket overhangs a walkway at head height, above the sensor''s scanning plane"},{"id":"e3","label":"Facilities note","detail":"The corridor floor is level concrete throughout"}],"question":"Given the sensor only scans one plane, which evidence describes a hazard 2D SLAM would miss entirely?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-mapping-and-slam-10-o1-c1', 'mission-vec-mapping-and-slam-10-o1', 1, 'multiple_choice', 'How does visual SLAM build a map without a dedicated range sensor?', '{"question":"How does visual SLAM build a map without a dedicated range sensor?","options":[{"id":"a","text":"It cannot, a range sensor is always required"},{"id":"b","text":"By tracking the same distinctive visual features across many camera frames and working out how the camera must have moved to see them shift that way"},{"id":"c","text":"By reading barcodes placed throughout the facility"},{"id":"d","text":"By measuring light intensity alone"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mapping-and-slam-10-o2-c1', 'mission-vec-mapping-and-slam-10-o2', 1, 'investigation', 'Which evidence describes what visual SLAM gives up in exchange for its lower cost and weight?', '{"evidence":[{"id":"e1","label":"Comparison note","detail":"Camera-only distance estimates are less precise than direct range measurements, especially in low-texture or poorly lit areas"},{"id":"e2","label":"Cost note","detail":"Cameras are typically cheaper and lighter than range sensors"},{"id":"e3","label":"Facilities note","detail":"The corridor has standard overhead lighting throughout"}],"question":"Which evidence describes what visual SLAM gives up in exchange for its lower cost and weight?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-mapping-and-slam-11-o1-c1', 'mission-vec-mapping-and-slam-11-o1', 1, 'drag_and_drop', 'Sort each property into an actual map-quality criterion or not.', '{"items":[{"id":"q1","text":"Whether the map agrees with itself across its own loop closures"},{"id":"q2","text":"How many colors the map is rendered in on a dashboard"},{"id":"q3","text":"Whether the map reflects the environment as it currently exists"},{"id":"q4","text":"Whether the map''s file size is under 10 megabytes"}],"targets":[{"id":"criterion","label":"Real quality criterion"},{"id":"not_criterion","label":"Not a quality criterion"}]}'::jsonb, '{"correctMapping":{"q1":"criterion","q2":"not_criterion","q3":"criterion","q4":"not_criterion"}}'::jsonb),
  ('mission-vec-mapping-and-slam-11-o2-c1', 'mission-vec-mapping-and-slam-11-o2', 1, 'multiple_choice', 'A map is perfectly self-consistent after loop closure. What does that alone prove?', '{"question":"A map is perfectly self-consistent after loop closure. What does that alone prove?","options":[{"id":"a","text":"That the map is guaranteed to match the current physical world"},{"id":"b","text":"That the map agrees with itself -- it does not by itself prove the world still looks the way the map says it does, unless backed by fresh sensor evidence"},{"id":"c","text":"Nothing at all, consistency is irrelevant to quality"},{"id":"d","text":"That the map no longer needs any sensor data to stay accurate"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-mapping-and-slam-12-o1-c1', 'mission-vec-mapping-and-slam-12-o1', 1, 'investigation', 'Which evidence proves, through the occupancy grids themselves, that the corridor''s geometry genuinely differs from the blueprint?', '{"evidence":[{"id":"e1","label":"Byte''s three-pass overlay","detail":"Occupancy grids from three independent SLAM passes, different days, different starting poses, all show the same corridor 1.8 meters narrower than the blueprint at the same location"},{"id":"e2","label":"Single anomalous reading","detail":"One range reading from an early test was rejected as noise and excluded from all three grids"},{"id":"e3","label":"Blueprint revision history","detail":"No formal revision exists for this section since the original survey"}],"question":"Which evidence proves, through the occupancy grids themselves, that the corridor''s geometry genuinely differs from the blueprint?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-mapping-and-slam-12-o2-c1', 'mission-vec-mapping-and-slam-12-o2', 1, 'investigation', 'Which evidence rules out accumulated drift as the explanation, because the discrepancy is too consistent across independent passes to be accumulated error?', '{"evidence":[{"id":"e1","label":"Drift research note","detail":"Uncorrected odometry drift typically grows with distance traveled and varies from run to run depending on surface, speed and turns"},{"id":"e2","label":"Byte''s three-pass overlay","detail":"This corridor''s discrepancy is identical in magnitude, location and shape across three independent passes -- a reproducibility drift does not have"},{"id":"e3","label":"Sensor calibration log","detail":"Range sensor accuracy stayed within rated spec throughout all three passes"}],"question":"Which evidence rules out accumulated drift as the explanation, because the discrepancy is too consistent across independent passes to be accumulated error?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-mapping-and-slam-12-o3-c1', 'mission-vec-mapping-and-slam-12-o3', 1, 'investigation', 'Which evidence proves the new SLAM-built map is internally consistent and trustworthy, not just visually clean?', '{"evidence":[{"id":"e1","label":"Loop closure report","detail":"The robot recognized its own starting junction at the end of the loop with a 94 percent feature match"},{"id":"e2","label":"Pose graph optimization result","detail":"Residual error across the entire closed loop settled near zero after optimization"},{"id":"e3","label":"Dashboard render","detail":"The map renders cleanly with no visual artifacts on the facility dashboard"}],"question":"Which evidence proves the new SLAM-built map is internally consistent and trustworthy, not just visually clean?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-mapping-and-slam-12-o4-c1', 'mission-vec-mapping-and-slam-12-o4', 1, 'boss_encounter', 'Having proven the corridor genuinely changed, ruled out drift and sensor error, and confirmed the new map is trustworthy, state Vector Division''s diagnosis.', '{"stages":[{"objectiveRef":"mission-vec-mapping-and-slam-12-o1","label":"Prove the corridor genuinely changed"},{"objectiveRef":"mission-vec-mapping-and-slam-12-o2","label":"Rule out drift and sensor error"},{"objectiveRef":"mission-vec-mapping-and-slam-12-o3","label":"Confirm the new map is trustworthy"}],"task":"State the diagnosis in one line: the corridor was genuinely altered by a past renovation nobody ever resurveyed -- the same undocumented-frame failure that misplaced the arm and drifted the mobile robots, now finally corrected at the source by letting the robot build and verify its own map instead of trusting an old blueprint blindly."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-mapping-and-slam-12-o1","mission-vec-mapping-and-slam-12-o2","mission-vec-mapping-and-slam-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-mapping-and-slam-01-o1-c1', 'orientation', 'Ask whether a map can be wrong the moment conditions change, or whether it is somehow immune to time.', 10, 1),
  ('mission-vec-mapping-and-slam-01-o1-c1', 'concept', 'A map is built once, from whatever sensors or surveys existed at that moment. It does not update itself afterward.', 20, 2),
  ('mission-vec-mapping-and-slam-01-o1-c1', 'solution', 'A map is a representation of the environment built at some specific time -- accurate only as of that moment, never guaranteed to stay true forever.', 30, 3),
  ('mission-vec-mapping-and-slam-01-o2-c1', 'orientation', 'Compare the size of the mismatch to what ordinary sensor noise usually looks like.', 10, 1),
  ('mission-vec-mapping-and-slam-01-o2-c1', 'solution', 'e1: a 1.8-meter mismatch over eleven meters is far too large to be noise -- that is the finding that makes this worth investigating.', 20, 2),

  ('mission-vec-mapping-and-slam-02-o1-c1', 'orientation', 'Ask whether a cell has actually been sensed at all before deciding it is free or occupied.', 10, 1),
  ('mission-vec-mapping-and-slam-02-o1-c1', 'solution', 'Occupied: the wall hit. Free: the beam path and the doorway the robot has repeatedly driven through. Unknown: the space behind the wall no beam has reached.', 20, 2),
  ('mission-vec-mapping-and-slam-02-o2-c1', 'orientation', 'Think about what guessing a cell''s state would actually cost if the guess were wrong.', 10, 1),
  ('mission-vec-mapping-and-slam-02-o2-c1', 'solution', 'Unknown honestly marks a cell no sensor has observed -- guessing free or occupied instead would misreport information the robot simply does not have.', 20, 2),

  ('mission-vec-mapping-and-slam-03-o1-c1', 'orientation', 'Nothing can be marked on the grid before a ray has actually been traced through it.', 10, 1),
  ('mission-vec-mapping-and-slam-03-o1-c1', 'solution', 'Sense the range reading, cast the ray, mark the free cells along it, then mark the occupied cell at the endpoint.', 20, 2),
  ('mission-vec-mapping-and-slam-03-o2-c1', 'orientation', 'Think about how much of a room one reading, from one position, can actually see.', 10, 1),
  ('mission-vec-mapping-and-slam-03-o2-c1', 'solution', 'A single scan only sees what is visible from one position -- overlapping scans from many positions are what let cell confidence actually build.', 20, 2),

  ('mission-vec-mapping-and-slam-04-o1-c1', 'orientation', 'Ask which one, localization or mapping, could be fully trusted first without the other.', 10, 1),
  ('mission-vec-mapping-and-slam-04-o1-c1', 'solution', 'Neither can go first cleanly -- accurate localization needs a good map, and a good map needs accurate localization to build it.', 20, 2),
  ('mission-vec-mapping-and-slam-04-o2-c1', 'orientation', 'The shortcut only works if the existing map can actually be trusted here.', 10, 1),
  ('mission-vec-mapping-and-slam-04-o2-c1', 'solution', 'e1: the corridor''s measured width already disagrees with the blueprint by 1.8 meters, so localizing against that blueprint would start from a false premise.', 20, 2),

  ('mission-vec-mapping-and-slam-05-o1-c1', 'orientation', 'Simultaneous does not mean two separate processes running in parallel and ignoring each other.', 10, 1),
  ('mission-vec-mapping-and-slam-05-o1-c1', 'solution', 'Position and map are estimated together, each cycle -- the current map refines the position, and the current position refines the map.', 20, 2),
  ('mission-vec-mapping-and-slam-05-o2-c1', 'orientation', 'New data has to arrive before either estimate can be refined.', 10, 1),
  ('mission-vec-mapping-and-slam-05-o2-c1', 'solution', 'Gather new data, update the pose estimate, update the map estimate, then repeat as the robot keeps moving.', 20, 2),

  ('mission-vec-mapping-and-slam-06-o1-c1', 'orientation', 'Loop closure is about recognition, not about ending anything.', 10, 1),
  ('mission-vec-mapping-and-slam-06-o1-c1', 'solution', 'Loop closure recognizes a previously visited place, which lets the accumulated error across the entire path in between be corrected at once.', 20, 2),
  ('mission-vec-mapping-and-slam-06-o2-c1', 'orientation', 'A shape alone is not proof -- ask what a strong feature match actually confirms that a rough shape cannot.', 10, 1),
  ('mission-vec-mapping-and-slam-06-o2-c1', 'solution', 'e1: a 94 percent feature match in the same relative arrangement confirms a genuine match, unlike merely similar-looking junction shape.', 20, 2),

  ('mission-vec-mapping-and-slam-07-o1-c1', 'orientation', 'A graph needs points before it can have connections between them, and connections before it can be optimized.', 10, 1),
  ('mission-vec-mapping-and-slam-07-o1-c1', 'solution', 'Nodes first, then edges, then a loop closure edge, then optimization to make the whole graph agree with itself.', 20, 2),
  ('mission-vec-mapping-and-slam-07-o2-c1', 'orientation', 'Think about whether it makes more sense to blame one segment or to share the correction fairly.', 10, 1),
  ('mission-vec-mapping-and-slam-07-o2-c1', 'solution', 'Optimization spreads the disagreement across every pose in the graph, adjusting each one slightly rather than patching only the closed segment.', 20, 2),

  ('mission-vec-mapping-and-slam-08-o1-c1', 'orientation', 'Think about what happens to a small error that is never given a chance to be corrected.', 10, 1),
  ('mission-vec-mapping-and-slam-08-o1-c1', 'solution', 'Uncorrected small errors accumulate over a run into a map that looks confident while being increasingly wrong -- that is drift.', 20, 2),
  ('mission-vec-mapping-and-slam-08-o2-c1', 'orientation', 'Look for the evidence describing drift in general, not the evidence describing this specific corridor.', 10, 1),
  ('mission-vec-mapping-and-slam-08-o2-c1', 'solution', 'e1: typical drift grows with distance and varies run to run -- that is the baseline signature to check any real discrepancy against.', 20, 2),

  ('mission-vec-mapping-and-slam-09-o1-c1', 'orientation', 'Ask what most indoor navigation actually needs to know about the floor ahead.', 10, 1),
  ('mission-vec-mapping-and-slam-09-o1-c1', 'solution', 'A flat occupancy grid from one scanning plane is enough because most navigation only needs to know whether the floor ahead is clear.', 20, 2),
  ('mission-vec-mapping-and-slam-09-o2-c1', 'orientation', 'Look for a hazard sitting above the sensor''s single scanning plane.', 10, 1),
  ('mission-vec-mapping-and-slam-09-o2-c1', 'solution', 'e2: a shelf bracket overhanging at head height sits above the scanning plane, so 2D SLAM would never see it.', 20, 2),

  ('mission-vec-mapping-and-slam-10-o1-c1', 'orientation', 'Think about what a camera can measure directly, and what it can only infer from change over time.', 10, 1),
  ('mission-vec-mapping-and-slam-10-o1-c1', 'solution', 'Visual SLAM tracks the same distinctive features across many frames and infers camera motion from how those features shift.', 20, 2),
  ('mission-vec-mapping-and-slam-10-o2-c1', 'orientation', 'Ask what a camera cannot measure directly that a range sensor can.', 10, 1),
  ('mission-vec-mapping-and-slam-10-o2-c1', 'solution', 'e1: camera-only distance estimates are less precise than direct range measurements, especially in low-texture or poorly lit areas.', 20, 2),

  ('mission-vec-mapping-and-slam-11-o1-c1', 'orientation', 'Ask whether each property says something about the map''s accuracy, or just about how it is displayed or stored.', 10, 1),
  ('mission-vec-mapping-and-slam-11-o1-c1', 'solution', 'Real criteria: self-consistency and reflecting the current environment. Not criteria: rendering colors and file size.', 20, 2),
  ('mission-vec-mapping-and-slam-11-o2-c1', 'orientation', 'Consistency is a statement about the map alone. Ask what it says, if anything, about the world outside the map.', 10, 1),
  ('mission-vec-mapping-and-slam-11-o2-c1', 'solution', 'Consistency proves the map agrees with itself. It does not, by itself, prove the world still looks the way the map claims -- that needs fresh sensor evidence.', 20, 2),

  ('mission-vec-mapping-and-slam-12-o1-c1', 'orientation', 'Look for the evidence built from repeated, independent measurement, not a single anomalous reading.', 10, 1),
  ('mission-vec-mapping-and-slam-12-o1-c1', 'solution', 'e1: three independent SLAM passes, on different days, all show the identical 1.8-meter discrepancy at the same location -- that is a genuine geometry difference.', 20, 2),
  ('mission-vec-mapping-and-slam-12-o2-c1', 'orientation', 'Recall drift''s actual signature from earlier this Act, then check whether this discrepancy matches it.', 10, 1),
  ('mission-vec-mapping-and-slam-12-o2-c1', 'solution', 'e2: drift varies run to run and grows with distance -- an identical discrepancy across three independent passes is not what drift looks like.', 20, 2),
  ('mission-vec-mapping-and-slam-12-o3-c1', 'orientation', 'A clean-looking render is not proof. Look for the evidence about the graph''s actual numbers.', 10, 1),
  ('mission-vec-mapping-and-slam-12-o3-c1', 'solution', 'e2: residual error across the entire closed loop settling near zero after optimization is what actually proves the new map is internally consistent.', 20, 2),
  ('mission-vec-mapping-and-slam-12-o4-c1', 'orientation', 'Connect this corridor back to the arm and the mobile robots -- the shape of the failure has not changed, only how it finally got fixed.', 15, 1),
  ('mission-vec-mapping-and-slam-12-o4-c1', 'solution', 'The corridor was genuinely altered by an unrecorded renovation -- the same undocumented-frame failure as the arm and the mobile robots, now corrected at the source by letting the robot build and verify its own map instead of trusting an old one blindly.', 25, 2);
